<?php declare(strict_types=1); require __DIR__.'/../config/config.php'; $db=db(); $error=''; if($_SERVER['REQUEST_METHOD']==='POST'){try{$u=trim($_POST['username']);$p=$_POST['password'];$role=$_POST['role'];if(strlen($u)<3||strlen($p)<6)throw new RuntimeException('Username must be 3+ characters and password 6+ characters.');$db->prepare('INSERT INTO users(username,password_hash,role,active) VALUES(?,?,?,1)')->execute([$u,password_hash($p,PASSWORD_DEFAULT),$role]);header('Location: users.php?saved=1');exit;}catch(Throwable $e){$error=$e->getMessage();}} $rows=$db->query('SELECT id,username,role,active,created_at FROM users ORDER BY username')->fetchAll(); ?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Users</title><link rel="stylesheet" href="style.css"></head><body><header><div class="brand">💊 <?=e(APP_NAME)?></div><nav><a href="index.php">Dashboard</a><a href="pos.php">POS</a><a href="inventory.php">Inventory</a><a class="active" href="manage.php">Management</a></nav></header><main><div class="page-title"><div><div class="eyebrow">STAFF ACCESS</div><h1>Users</h1><p>Create staff accounts with pharmacy roles.</p></div></div><?php if($error):?><div class="alert"><?=e($error)?></div><?php endif;?><?php if(isset($_GET['saved'])):?><div class="success">✓ User created.</div><?php endif;?><section class="panel"><h2>Add User</h2><form method="post" class="grid"><label>Username<input name="username" required></label><label>Password<input type="password" name="password" required></label><label>Role<select name="role"><option value="cashier">Cashier</option><option value="pharmacist">Pharmacist</option><option value="manager">Manager</option><option value="admin">Admin</option></select></label><button class="btn">Create User</button></form></section><section class="panel"><table><tr><th>Username</th><th>Role</th><th>Status</th><th>Created</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['username'])?></td><td><?=e(ucfirst($r['role']))?></td><td><?=$r['active']?'Active':'Disabled'?></td><td><?=e($r['created_at'])?></td></tr><?php endforeach;?></table></section></main></body></html>